--region lifecycle
function DreamAdventuresStoreDialog:__init()
    self._storeData = {}
    self._tabData = {}
    self._selectedTabIndex = 1
    self._events = {}
    self._products = {}
end

function DreamAdventuresStoreDialog:__delete()
    self._storeData = {}
    self._tabData = nil
    self._selectedTabIndex = nil
    self._events = nil
    self._products = nil 
end

function DreamAdventuresStoreDialog:OnFocus(focus)
    if focus then
        local hpGoodsId = DreamAdventuresMgr:GetStoreCurrency()
        CfUtils.RefreshTopGoods({hpGoodsId})
    end
end

function DreamAdventuresStoreDialog:OnInitialize()
    self:InitHandler()
    self:InitData()
end

function DreamAdventuresStoreDialog:OnFinalize()
    for k, v in pairs(self._events) do
        Events.RemoveListener(k, v)
    end

    if not isNull(self._timer) then
        CDTimerModule.GetInstance():RemoveCD(self._timer)
        self._timer = nil
    end
    
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function DreamAdventuresStoreDialog:InitHandler()
    self._events[Constants.EventNames.DreamAdventuresStoreTabEvent] = Events.AddListener(Constants.EventNames.DreamAdventuresStoreTabEvent, Bind(self, self.OnLeftToggleClickHandler))
    self._events[Constants.EventNames.DreamAdventuresStoreBuy] = Events.AddListener(Constants.EventNames.DreamAdventuresStoreBuy, Bind(self, self.StoreBuyEventHandler))
end

function DreamAdventuresStoreDialog:InitData()
    local activityId = DreamAdventuresMgr:GetActivityId()
    local activityType = ActivityConstants.ActivityType.ConstractFood
    GameUtils.Request(Interfaces.DreamAdventuresStore, {activityUuid = activityId, activityType = activityType}, Bind(self, self.StoreResponseHandler))
end
--endregion init

--region handler
---商城home回调处理
function DreamAdventuresStoreDialog:StoreResponseHandler(request, response)
    local data = self:ConvertActivityStoreData(response.data)
    self:SetStoreData(data)
    self:SetProducts(self:GroupBy())
    self:RefreshUI()
end

---列表cell处理
function DreamAdventuresStoreDialog:RefreshItemByIndex(go, index)
    local luaIndex = index + 1
    local cellData = self._groupedProducts[luaIndex]
    local scr = CfUtils.GetLuaScr(go, DreamAdventuresConstants.ScrPath.DreamAdventuresStoreCell)
    scr:Refresh(cellData)
end

function DreamAdventuresStoreDialog:OnLeftToggleClickHandler(products, isUnlock, preShopName)
    if not isUnlock then
        CfUtils.FillText(self.TxtTips, localize("购买_name_所有物品后解锁", {_name_=preShopName}))
        CfUtils.SetActive(self.ImgBgLock, true)
    else
        CfUtils.SetActive(self.ImgBgLock, false)
    end

    self._groupedProducts = checkTable(products)
    if not self.ScrollView.mLoopListView.IsListViewInit then
        self.ScrollView:InitListView(table.count(products), Bind(self, self.RefreshItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, table.count(products))
    end
    CfUtils.StopAnimation(self.Root)
    CfUtils.PlayAnimation(self.Root, "ActivityMidFestivalShopDialog_Entry")
end

---商城购买
function DreamAdventuresStoreDialog:StoreBuyEventHandler()
    self:InitData()
end
--endregion handler

