--endregion public

--region private
---刷新UI
function DreamAdventuresStoreDialog:RefreshUI()
    self:RefreshTime()
    self:RefreshTab()
end

---刷新页签
function DreamAdventuresStoreDialog:RefreshTab()
    if not next(self:GetProducts()) then return end

    local viewport = self.CommonTabToggleLeft:Find("TabListView/Viewport")
    if isNotNull(viewport) then
        CfUtils.SetActive(viewport, #self:GetProducts() > 1)
    end
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeft, DreamAdventuresConstants.ScrPath.StoreTabToggleLeft)
    if scr then
        scr:Refresh(self:GetProducts())
    end
end

function DreamAdventuresStoreDialog:RefreshTime()
    local time = self:GetStoreData().remainingTimes
    if not isNull(self._timer) then
        CDTimerModule.GetInstance():RemoveCD(self._timer)
        self._timer = nil
    end

    self._timer = CDTimerModule.GetInstance():AddCD(1, function(_, _, delta)
        CfUtils.FillText(self.TextTime2, CfUtils.GetTimeHMS(time))
        time = time - delta
    end, CountDownTime, true, true)
end

---GroupBy 将products分组
function DreamAdventuresStoreDialog:GroupBy()
    local hash = {}
    local list = {}
    local storeData = self:GetStoreData()
    for i, v in ipairs(storeData.products) do
        ---@type MidFestivalProductDojo
        local product = v
        if isNull(hash[checkString(product.goodsGroup)]) then
            hash[checkString(product.goodsGroup)] = {}
        end
        table.insert(hash[checkString(product.goodsGroup)], product)
    end

    -- 辅助结构
    local indexes = {}
    local i = 1
    for k, v in pairs(hash) do
        local index = {
            pos = checkNumber(k),
            realPos = i
        }
        table.insert(indexes, index)
        table.insert(list, v)
        i = i + 1
    end

    table.sort(indexes, function(a, b)
        return a.pos < b.pos
    end)

    local retList = {}
    for _, index in ipairs(indexes) do
        table.insert(retList, list[index.realPos])
    end

    for _, group in ipairs(retList) do
        table.sort(group, function(a, b)
            return checkNumber(a.pos) < checkNumber(b.pos)
        end)
    end

    return retList
end

---转换活动商店数据
function DreamAdventuresStoreDialog:ConvertActivityStoreData(jsonData)
    local ret = {}
    ret.remainingTimes = jsonData.remainingTimes
    ret.products = {}
    for _, v in ipairs(jsonData.products) do
        local goodsList = CfUtils.Split(v.goodsId)
        local numList = CfUtils.Split(v.num)
        local rewards = {}

        for i = 1, #goodsList do
            local reward = {
                goodsId = goodsList[i],
                num = numList[i]
            }
            table.insert(rewards, reward)
        end

        ---@type MidFestivalProductDojo
        local product = MidFestivalProductDojo.New()
        product:Fill(v)
        product.rewards = rewards
        table.insert(ret.products, product)
    end
    return ret
end
